def add_categories(apps, schema_editor):
    """The two types that existed become editable categories; products keep their type."""
    Category = apps.get_model("store", "Category")
    Product = apps.get_model("store", "Product")
    books, _ = Category.objects.get_or_create(
        name="Kitoblar", defaults={"is_book": True, "sort_order": 10}
    )
    items, _ = Category.objects.get_or_create(
        name="Mahsulotlar", defaults={"is_book": False, "sort_order": 20}
    )
    Product.objects.filter(kind="book", category__isnull=True).update(category=books)
    Product.objects.filter(kind="item", category__isnull=True).update(category=items)


